  border-radius: 6px;
  background: #ffffff;
  color: #2d5d5a;""","""  border: 1px solid #2d5d5a;
  border-radius: 6px;
  background: #2d5d5a;
  color: #ffffff;"""),
("""  border-top: 1px solid #dfe3e0;
  color: #6b7574;
}""","""  gap: 16px;
