  }

  .search {
    flex: none;
  }

  .routes {
    padding: 0 20px 32px;
  }
}
"""
open(p,'w').write(s)
h=open('index.html').read()
a='<h1>Hire a narrowboat for a week on the canal</h1>'
assert a in h
