@font-face {
  font-family: "Inter";
  font-weight: 400;
  src: url("fonts/inter-latin-400-normal.woff2") format("woff2");
}

@font-face {
  font-family: "Inter";
  font-weight: 500;
  src: url("fonts/inter-latin-500-normal.woff2") format("woff2");
}

@font-face {
  font-family: "Source Serif 4";
  font-weight: 400;
  src: url("fonts/source-serif-4-latin-400-normal.woff2") format("woff2");
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  font-family: "Inter", sans-serif;
  font-size: 16px;
  line-height: 1.55;
  color: #26302f;
  background: #f7f8f6;
}

a {
  color: inherit;
}

/* Hold every band of the page in one centered column on wide screens */
.site-header,
.hero,
.routes {
  max-width: 1120px;
  margin-left: auto;
  margin-right: auto;
}

.site-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 22px 64px;
}

.logo {
  font-family: "Source Serif 4", serif;
  font-size: 20px;
  text-decoration: none;
}

.site-nav a {
  margin-left: 28px;
  text-decoration: none;
  font-size: 16px;
}

.hero {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  gap: 64px;
  padding: 48px 64px 32px;
}

.hero-text {
