@font-face {
  font-family: "Inter";
  font-weight: 400;
  src: url("fonts/inter-latin-400-normal.woff2") format("woff2");
}

@font-face {
  font-family: "Inter";
  font-weight: 500;
  src: url("fonts/inter-latin-500-normal.woff2") format("woff2");
}

@font-face {
  font-family: "Source Serif 4";
  font-weight: 400;
  src: url("fonts/source-serif-4-latin-400-normal.woff2") format("woff2");
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  font-family: "Inter", sans-serif;
  font-size: 16px;
  line-height: 1.55;
  color: #26302f;
  background: #f7f8f6;
}

a {
  color: inherit;
}

/* Hold every band of the page in one centered column on wide screens */
.site-header,
.hero,
.routes {
  max-width: 1120px;
  margin-left: auto;
  margin-right: auto;
}

.site-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 22px 64px;
}

.logo {
  font-family: "Source Serif 4", serif;
  font-size: 20px;
  text-decoration: none;
}

.site-nav a {
  margin-left: 28px;
  text-decoration: none;
  font-size: 16px;
}

.hero {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  gap: 64px;
  padding: 48px 64px 32px;
}

.hero-text {
  max-width: 600px;
}

h1 {
  margin: 0 0 16px;
  font-family: "Source Serif 4", serif;
  font-size: 36px;
  font-weight: 400;
  line-height: 1.2;
  color: #26302f;
}

.lead {
  margin: 0 0 28px;
  font-size: 20px;
  line-height: 1.5;
  color: #26302f;
}

/* A plain text link: the form's Search button is the one primary action */
.button {
  color: #2d5d5a;
  font-weight: 500;
  text-underline-offset: 3px;
}

.search {
  flex: 0 0 340px;
  padding: 22px;
  border: 1px solid #dfe3e0;
  border-radius: 8px;
  background: #ffffff;
}

.search-title {
  margin-bottom: 14px;
  font-weight: 500;
}

.search label {
  display: block;
  margin-bottom: 12px;
  font-size: 14px;
  color: #5f6968;
}

.search select,
.search input {
  display: block;
  width: 100%;
  margin-top: 4px;
  padding: 8px 10px;
  border: 1px solid #cfd5d2;
  border-radius: 6px;
  background: #ffffff;
  font: inherit;
  font-size: 16px;
  color: #26302f;
}

.search button {
  width: 100%;
  margin-top: 6px;
  padding: 10px;
  border: 1px solid #2d5d5a;
  border-radius: 6px;
  background: #2d5d5a;
  color: #ffffff;
  font: inherit;
  font-weight: 500;
}

.routes {
  padding: 0 64px;
}

h2 {
  margin: 0 0 10px;
  font-size: 16px;
  font-weight: 500;
}

.routes ul {
  max-width: 600px;
  margin: 0;
  padding: 0;
  list-style: none;
}

.routes li {
  display: flex;
  justify-content: space-between;
  gap: 16px;
  padding: 8px 0;
  border-top: 1px solid #dfe3e0;
  color: #5f6968;
}

/* Keep "7 nights, 38 locks" on one line */
.routes li span:last-child {
  white-space: nowrap;
}

.route-name {
  color: #26302f;
}

/* Phones and narrow windows: one column, menu in one wrapping row */
@media (max-width: 760px) {
  .site-header {
    flex-wrap: wrap;
    gap: 8px 0;
    padding: 16px 20px;
  }

  .site-nav {
    display: flex;
    flex-wrap: wrap;
    gap: 4px 20px;
  }

  .site-nav a {
    margin-left: 0;
    white-space: nowrap;
  }

  .hero {
    flex-direction: column;
    align-items: stretch;
    gap: 28px;
    padding: 24px 20px 32px;
  }

  .search {
    flex: none;
  }

  .routes {
    padding: 0 20px 32px;
  }
}

